package org.sleepwell.app;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;

/** Private settings/storage only. No AlarmActivity, sensors, keys or scheduled alarm runtime. */
public final class AlarmInputsStorageTest {
    @Test public void absentLegacyInputsAreUnchangedAndExplicitChoicesPersistWithPortableInactiveRestore()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){Alarm original=f.load();assertEquals(AlarmInputs.DEFAULT,original.inputs);assertFalse(original.json().has("inputs"));Alarm draft=Alarm.read(original.json());draft.inputs=new AlarmInputs(true,AlarmInputs.Keys.SNOOZE);Alarm saved=AlarmSkips.edit(f.c,store,draft,original,true);assertTrue(f.load().inputs.flip);assertEquals(AlarmInputs.Keys.SNOOZE,f.load().inputs.keys);assertEquals(original.hour,saved.hour);assertEquals(original.days,saved.days);JSONObject backup=store.backup();Backup.validate(backup);Backup.restoreData(store,backup);assertFalse(store.alarm(1).enabled);assertEquals(draft.inputs,store.alarm(1).inputs);}}
    @Test public void strictInputMetadataRejectsUnknownAndTypeConfusedValuesWithoutAllocatingAnything()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture()){for(Object raw:new Object[]{JSONObject.NULL,"SNOOZE",new JSONObject().put("flip","true").put("keys","SNOOZE"),new JSONObject().put("flip",true).put("keys","DISMISS"),new JSONObject().put("flip",true).put("keys","IGNORE").put("extra",1)}){JSONObject json=f.load().json().put("inputs",raw);Alarm invalid=Alarm.read(json);assertTrue(invalid.inputsInvalid);assertEquals(AlarmInputs.DEFAULT,invalid.inputs);assertTrue(invalid.json().has("inputs"));assertThrows(IllegalArgumentException.class,()->new AlarmDefaults(invalid));}}}
    @Test public void behaviorDefaultsKeepInputChoicesWhileLegacyTemplatesRemainExactDefault()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture()){Alarm source=f.load();String legacy=AlarmDefaultsJson.encode(new AlarmDefaults(source));Alarm templateAlarm=AlarmDefaultsJson.decode(legacy).create(3);assertEquals(AlarmInputs.DEFAULT,templateAlarm.inputs);source.inputs=new AlarmInputs(true,AlarmInputs.Keys.IGNORE);String saved=AlarmDefaultsJson.encode(new AlarmDefaults(source));assertEquals(source.inputs,AlarmDefaultsJson.decode(saved).create(4).inputs);JSONObject bad=new JSONObject(saved);bad.getJSONObject("settings").getJSONObject("inputs").put("flip",1);assertThrows(IllegalArgumentException.class,()->AlarmDefaultsJson.decode(bad.toString()));assertEquals(AlarmInputs.DEFAULT,f.load().inputs);}}
}
